 ans<-data.table(datasets_estimable=estn,k=k,pooled_difference=NA_real_,se=NA_real_,ci_lo=NA_real_,ci_hi=NA_real_,tau2=NA_real_,I2=NA_real_,method='REML',interval='Knapp-Hartung',status=if(k<5L)'fewer_than_five_positive_variance_datasets'else'fit_failed',message='')
